// Collapse every retrieval branch into one payload for synthesis.
// Each branch returned { domain, agent, findings, evidence, trace }.
const ctx = $('Carry context').first().json;

const findings = [];
const evidence = [];
const trace = [...(ctx.classify_trace || [])];
const domainsUsed = [];

for (const item of $input.all()) {
  const j = item.json || {};
  if (j.domain) domainsUsed.push(j.domain);
  if (j.findings && Object.keys(j.findings).length) findings.push(j.findings);
  if (Array.isArray(j.evidence)) evidence.push(...j.evidence);
  if (Array.isArray(j.trace)) trace.push(...j.trace);
}

// de-duplicate evidence by id; branches share the planner pass so overlap happens
const seen = new Set();
const uniqueEvidence = [];
for (const e of evidence) {
  if (!e || !e.id || seen.has(e.id)) continue;
  seen.add(e.id);
  uniqueEvidence.push(e);
}

// renumber the trace so the reasoning panel reads in order
trace.forEach((step, i) => { if (step) step.seq = i + 1; });

return [{
  json: {
    message: ctx.message,
    session_id: ctx.session_id,
    lat: ctx.lat,
    lon: ctx.lon,
    place: ctx.place,
    destination: ctx.destination || null,
    intent: ctx.intent,
    domains_used: domainsUsed,
    findings,
    evidence: uniqueEvidence,
    trace,
  }
}];
